class Solution {
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
public:
    long long interchangeableRectangles(vector<vector<int>>& rectangles) {
        unordered_map<long long, int> count;
        long long result = 0;
        for (auto& r : rectangles) {
            int w = r[0], h = r[1];
            int g = gcd(w, h);
            long long key = (long long)(w / g) * 100001 + (h / g);
            result += count[key];
            count[key]++;
        }
        return result;
    }
};
